function mergeConversation(dto){const c=fromConversationDTO(dto,viewerId);if(!hasConversationMessages(c))throw Object.assign(Error('Empty conversation response'),{code:'VALIDATION'});const piece=findPost(c.listingId);if(piece&&isEngagementCount(dto.conversationCount))piece.conversationCount=dto.conversationCount;conversations=[c,...conversations.filter(item=>item.id!==c.id)];return c}
