async function initializeMarketData(){marketLoading=true;marketLoadFailed=false;renderMarketDataState();try{for(const method of ['bootstrap','uploadImage','createListing','updateListing','deleteListing','setFavorite','openConversation','sendMessage','updateProfile'])if(typeof repository[method]!=='function')throw Error('Missing repository method');const data=await repository.bootstrap();viewerId=typeof data.viewer?.id==='string'?data.viewer.id:null;loadChatReadMarks();posts=(Array.isArray(data.listings)?data.listings:[]).map(p=>fromListingDTO(p,viewerId)).filter(Boolean);favorites=new Set(Array.isArray(data.favorites)?data.favorites:[]);conversations=(Array.isArray(data.conversations)?data.conversations:[]).filter(c=>c&&typeof c.id==='string').map(c=>fromConversationDTO(c,viewerId)).filter(hasConversationMessages);const value=data.profile||{};profile=normalizeProfile(value);repositoryReady=true;connectMarketUpdates()}catch{marketLoadFailed=true;repositoryReady=false}finally{marketLoading=false;renderMarketDataState();if(document.body.dataset.view==='market')render()}}

