function getAsset(name){if(assetCache.has(name))return assetCache.get(name);const data=assets[name];if(!data)return '';let url=data;try{const comma=data.indexOf(','),type=data.slice(5,data.indexOf(';')),binary=atob(data.slice(comma+1)),bytes=new Uint8Array(binary.length);for(let i=0;i<binary.length;i++)bytes[i]=binary.charCodeAt(i);url=URL.createObjectURL(new Blob([bytes],{type}))}catch{}assetCache.set(name,url);return url}
