const ARTIST_SEARCH_ALIASES={"van gogh":"고흐 반고흐 빈센트 반 고흐","cézanne":"세잔 폴 세잔","hokusai":"호쿠사이 가쓰시카 호쿠사이","klimt":"클림트 구스타프 클림트","leonardo":"다빈치 레오나르도 다 빈치","david":"다비드 자크 루이 다비드","picasso":"피카소 파블로 피카소"};
function artistSearchAliases(name){const value=String(name||'').toLocaleLowerCase();return Object.entries(ARTIST_SEARCH_ALIASES).filter(([key])=>value.includes(key)).map(([,aliases])=>aliases).join(' ')}
const searchText=value=>String(value||'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').normalize('NFC').toLocaleLowerCase();
const compactSearch=value=>searchText(value).replace(/[^\p{L}\p{N}]/gu,'');
const RELATED_SEARCH_GROUPS=[{"id":"van-gogh","weight":3,"aliases":["vincent van gogh","van gogh","vangogh","빈센트 반 고흐","반고흐","반 고흐","고흐"]},{"id":"cezanne","weight":3,"aliases":["paul cezanne","cézanne","cezanne","폴 세잔","세잔"]},{"id":"hokusai","weight":3,"aliases":["katsushika hokusai","hokusai","가쓰시카 호쿠사이","호쿠사이"]},{"id":"klimt","weight":3,"aliases":["gustav klimt","klimt","구스타프 클림트","클림트"]},{"id":"leonardo","weight":3,"aliases":["leonardo da vinci","da vinci","leonardo","레오나르도 다빈치","다 빈치","다빈치"]},{"id":"david","weight":3,"aliases":["jacques louis david","jacques-louis david","david","자크 루이 다비드","다비드"]},{"id":"picasso","weight":3,"aliases":["pablo picasso","picasso","파블로 피카소","피카소"]},{"id":"print","weight":1,"aliases":["art print","fine art print","fine-art print","archival print","pigment print","prints","print","poster","posters","reproduction","아트 프린트","아트프린트","프린트","포스터","복제화","판화"]},{"id":"wall-art","weight":0.5,"aliases":["wall art","그림","벽그림"]},{"id":"painting","weight":1,"aliases":["paintings","painting","페인팅","회화"]},{"id":"drawing","weight":1.5,"aliases":["drawings","drawing","sketches","sketch","드로잉","스케치","소묘"]},{"id":"oil","weight":2,"aliases":["oil painting","oil on canvas","oil","오일 페인팅","오일페인팅","유화"]},{"id":"watercolor","weight":2,"aliases":["watercolor","watercolour","수채화","수채"]},{"id":"acrylic","weight":2,"aliases":["acrylic","아크릴화","아크릴"]},{"id":"ceramic","weight":1.5,"aliases":["ceramics","ceramic","porcelain","도자기","세라믹","도자"]},{"id":"vase","weight":2,"aliases":["vases","vase","화병","꽃병"]},{"id":"abstract","weight":2,"aliases":["abstract","추상화","추상"]},{"id":"landscape","weight":2,"aliases":["landscape","landscapes","scenery","풍경화","풍경"]},{"id":"portrait","weight":2,"aliases":["portraits","portrait","초상화","초상","인물화","인물"]},{"id":"still-life","weight":2,"aliases":["still life","still-life","정물화","정물"]},{"id":"flower","weight":2,"aliases":["flowers","flower","floral","꽃그림","꽃 그림","꽃"]},{"id":"roses","weight":3,"aliases":["roses","rose","장미"]},{"id":"sunflowers","weight":3,"aliases":["sunflowers","sunflower","해바라기"]},{"id":"wave","weight":2.5,"aliases":["great wave","waves","wave","큰 파도","큰파도","가나가와","파도"]},{"id":"starry-night","weight":3,"aliases":["the starry night","starry night","별이 빛나는 밤","별이빛나는밤","별빛","별밤"]},{"id":"mona-lisa","weight":3,"aliases":["mona lisa","monalisa","모나리자"]},{"id":"blue","weight":1.5,"aliases":["blue","파란색","파랑","파란","블루"]},{"id":"red","weight":1.5,"aliases":["red","빨간색","빨강","빨간","붉은","레드"]},{"id":"yellow","weight":1.5,"aliases":["yellow","노란색","노랑","노란","옐로"]},{"id":"green","weight":1.5,"aliases":["green","초록색","초록","녹색","그린"]},{"id":"ivory","weight":1.5,"aliases":["ivory","아이보리"]},{"id":"framed","weight":1,"aliases":["frame included","framed","액자 포함","액자포함","액자"]},{"id":"vintage","weight":1.5,"aliases":["vintage","빈티지"]},{"id":"photography","weight":1.5,"aliases":["photography","photograph","photographs","photo","photos","사진","사진작품"]},{"id":"sculpture","weight":1.5,"aliases":["sculpture","sculptures","statue","statues","relief","art toy","조각","조각상","입체","부조","아트토이"]},{"id":"craft","weight":1.5,"aliases":["craft","crafts","handmade","textile","textiles","weaving","glass art","공예","수공예","직물","섬유","유리공예","목공예"]},{"id":"digital","weight":1.5,"aliases":["digital art","digital","video art","video","animation","sound art","디지털","디지털아트","미디어","영상","애니메이션","사운드아트"]},{"id":"mixed-media","weight":1.5,"aliases":["mixed media","mixed-media","collage","installation","복합","혼합매체","콜라주","설치","설치미술"]},{"id":"jewelry","weight":1.5,"aliases":["jewelry","jewellery","art jewelry","art jewellery","주얼리","쥬얼리","장신구","아트 주얼리"]},{"id":"jewelry-ring","weight":2,"aliases":["ring","rings","반지"]},{"id":"jewelry-necklace","weight":2,"aliases":["necklace","necklaces","목걸이"]},{"id":"jewelry-earring","weight":2,"aliases":["earring","earrings","귀걸이"]},{"id":"jewelry-bracelet","weight":2,"aliases":["bracelet","bracelets","팔찌"]},{"id":"jewelry-brooch","weight":2,"aliases":["brooch","brooches","브로치"]}].map(group=>({...group,aliases:[...new Set(group.aliases.map(searchText))]}));
const SEARCH_COLOR_GROUPS=new Set(['blue','red','yellow','green','ivory']);
const SEARCH_STOP_WORDS=new Set(['art','artwork','artworks','작품','추천','찾기','찾아줘','판매','구매','buy','for','the','a','an','of','with','and','please']);
const escapedSearch=value=>value.replace(/[.*+?^{}$()|[\]\\]/g,'\\$&');
function aliasPattern(alias){return /^[a-z0-9 .-]+$/.test(alias)?new RegExp('(^|[^a-z0-9])('+escapedSearch(alias).replace(/\s+/g,'\\s+')+')(?=$|[^a-z0-9])','g'):new RegExp(escapedSearch(alias).replace(/\s+/g,'\\s*'),'g')}
const SEARCH_ALIASES=RELATED_SEARCH_GROUPS.flatMap(group=>group.aliases.map(alias=>({group,alias}))).sort((a,b)=>b.alias.length-a.alias.length);
function relatedSearchQuery(raw){
 const text=searchText(raw),terms=new Map();let rest=text;
 for(const {group,alias}of SEARCH_ALIASES){const pattern=aliasPattern(alias);if(pattern.test(rest)){terms.set(group.id,{id:group.id,weight:group.weight,group});rest=rest.replace(aliasPattern(alias),' ')}}
 for(const word of rest.match(/[\p{L}\p{N}]+/gu)||[]){if(SEARCH_STOP_WORDS.has(word))continue;terms.set('word:'+word,{id:'word:'+word,word,weight:2})}
 return{text,compact:compactSearch(text),terms:[...terms.values()]};
}
function matchesSearch(p,query){
 const kind=COPY[KIND_KEYS[p.kind]]||COPY.kind_original;
 const title=searchText([p.title,workText(p,'title','en'),workText(p,'title','ko')].join(' '));
 const haystack=searchText([title,p.description,p.category,p.region,sellerName(p),p.artist,artistSearchAliases(p.artist),p.medium,p.dimensions,pick(kind,'en'),pick(kind,'ko'),workText(p,'description','en'),workText(p,'description','ko'),categoryName(p.category,'en'),categoryName(p.category,'ko'),areaName(p,'en'),areaName(p,'ko'),['회화','드로잉','아트 프린트','사진'].includes(p.category)?'wall art 그림':'',p.framed==='yes'?'frame included 액자포함':'',p.condition==='vintage'?'vintage 빈티지':'',Array.isArray(p.tags)?p.tags.filter(tag=>typeof tag==='string').join(' '):''].join(' '));
 const compact=compactSearch(haystack);
 if(query.compact&&compact.includes(query.compact))return true;
 if(!query.terms.length)return true;
 // Infer broad subjects only from concrete words in the listing, never from arbitrary artwork IDs.
 const subjects=new Set(RELATED_SEARCH_GROUPS.filter(group=>group.aliases.some(alias=>aliasPattern(alias).test(haystack))).map(group=>group.id));
 if(subjects.has('roses')||subjects.has('sunflowers'))subjects.add('flower');
 const requestedColors=query.terms.filter(term=>SEARCH_COLOR_GROUPS.has(term.id));
 if(requestedColors.length&&!requestedColors.some(term=>subjects.has(term.id)))return false;
 let matched=0,total=0;
 for(const term of query.terms){total+=term.weight;const hit=term.group?subjects.has(term.id):haystack.includes(term.word)||(term.word.length>=2&&compact.includes(compactSearch(term.word)));if(hit)matched+=term.weight}
 // Specific artist/subject words carry more weight than broad words such as print or painting.
 return matched>0&&matched/total>=.55;
}

const revealedPieces=new Set();let cardRevealObserver=null;
function revealCards(){
 cardRevealObserver?.disconnect();
 if(matchMedia('(prefers-reduced-motion: reduce)').matches||typeof IntersectionObserver!=='function')return;
 if(!cardRevealObserver)cardRevealObserver=new IntersectionObserver(entries=>{
  for(const entry of entries){if(!entry.isIntersecting)continue;const card=entry.target;revealedPieces.add(card.dataset.motionId);card.classList.remove('motion-pending');card.classList.add('motion-enter');cardRevealObserver.unobserve(card)}
 },{root:$('.market-scroll'),threshold:.08,rootMargin:'0px 0px 24px 0px'});
 $$('#product-grid .product-card').forEach((card,index)=>{
  const id=card.querySelector('[data-product]')?.dataset.product;if(!id||revealedPieces.has(id))return;
  card.dataset.motionId=id;card.style.setProperty('--card-delay',Math.min(index,3)*45+'ms');card.classList.add('motion-pending');cardRevealObserver.observe(card);
 });
}
// Popularity uses a server aggregate when provided; local preview uses this browser's actual favorites.
const isEngagementCount=value=>Number.isSafeInteger(value)&&value>=0;
const engagementNumberFormat=new Intl.NumberFormat(locale);
function popularityScore(piece){return isEngagementCount(piece.favoriteCount)?piece.favoriteCount:Number(favorites.has(piece.id))}
function render(){
 const rawQuery=$('#search').value.trim(),query=rawQuery?relatedSearchQuery(rawQuery):null,mineStatus=$('#mine-status').value;
 const items=allPosts().filter(p=>(mode==='all'||mode==='favorites'&&favorites.has(p.id)||mode==='mine'&&p.mine)&&(category==='전체'||p.category===category)&&(!query||matchesSearch(p,query))&&(mode!=='mine'||mineStatus==='all'||p.status===mineStatus));
 const sort=$('#sort').value,newest=(a,b)=>b.created-a.created||String(a.id).localeCompare(String(b.id));items.sort(sort==='popular'?(a,b)=>popularityScore(b)-popularityScore(a)||newest(a,b):sort==='price-low'?(a,b)=>CURRENCY_ORDER.indexOf(currencyOf(a))-CURRENCY_ORDER.indexOf(currencyOf(b))||a.priceMinor-b.priceMinor||newest(a,b):sort==='price-high'?(a,b)=>CURRENCY_ORDER.indexOf(currencyOf(a))-CURRENCY_ORDER.indexOf(currencyOf(b))||b.priceMinor-a.priceMinor||newest(a,b):newest);
 $('#product-grid').innerHTML=renderCurrencyResults(items,sort);revealCards();$('#results-status').textContent=t(items.length===1?'result_one':'result_many',{count:items.length});$('#list-heading').innerHTML=reviewedLabel(mode==='favorites'?'list_saved':mode==='mine'?'list_mine':'list_all')+' <span id="result-count">'+items.length+'</span>';$('#market-title').textContent=t(mode==='favorites'?'market_saved_title':mode==='mine'?'market_mine_title':'market_title');
 updateMarketNavigation();renderStudio();renderMarketDataState();$('[data-i18n="market_footer"]').textContent=t(isPreview?'market_footer':'market_footer_live');$('[data-i18n="chat_disclaimer"]').textContent=t(isPreview?'chat_disclaimer':'chat_welcome');$$('.category-chip').forEach(button=>{const active=button.dataset.category===category;button.classList.toggle('active',active);button.setAttribute('aria-pressed',String(active))});
 $('#mine-status').hidden=mode!=='mine';
$('#search-clear').hidden=!query;$('#empty-state').hidden=items.length!==0;$('#empty-title').textContent=t(query?'empty_search':mode==='favorites'?'empty_saved':mode==='mine'?'empty_mine':'empty_filtered');$('#empty-text').textContent=t(!query&&mode==='favorites'?'empty_saved_text':!query&&mode==='mine'?'empty_mine_text':'empty_search_text');$('#reset-filters span').textContent=t(mode==='mine'&&!posts.length?'sell':'browse_all');
 updateUnreadBadge();syncMarketLabels();
}

function setMode(value){mode=['all','favorites','mine'].includes(value)?value:'all';resetMarketFilters();render();$('.market-scroll').scrollTop=0}

const HOME_SIGNATURES=Object.freeze([
 'Connecting art to its next chapter.',
 'A new home for the art you love.',
 'From one collection to the next.',
 'Find a piece that feels like you.',
 'Every work has another story to tell.'
]);
function chooseHomeSignature(){const heading=document.getElementById('gallery-motto');if(!heading)return;let previous=-1;try{previous=Number(sessionStorage.getItem('piecenoa.home.signature.v1')??-1)}catch{}const choices=HOME_SIGNATURES.map((_,i)=>i).filter(i=>i!==previous),index=choices[Math.floor(Math.random()*choices.length)];heading.textContent=HOME_SIGNATURES[index];heading.classList.remove('is-korean');try{sessionStorage.setItem('piecenoa.home.signature.v1',String(index))}catch{}}
function applyRoute(){
 clearTimeout(enterTimer);$$('dialog[open]').forEach(dialog=>dialog.close());
 const market=['#community','#market'].includes(location.hash),wasMarket=$('#home').hidden;
 document.documentElement.lang='en';
 $('#home').hidden=market;$('#market').hidden=!market;$('#home').classList.remove('is-leaving','is-portal-white','is-direct-leaving');
 document.body.dataset.view=market?'market':'home';gallery3D?.setVisible(!market);
 if(market){render();$('#market').classList.remove('community-arriving');void $('#market').offsetWidth;$('#market').classList.add('community-arriving');$('#market-title').focus({preventScroll:true})}
 else{chooseHomeSignature();if(wasMarket){gallery3D?.reset();$('[data-auth-open]').focus({preventScroll:true})}}
 updateTitle();
}
function enter(value='all'){
 if($('#home').classList.contains('is-leaving'))return;
 setMode(value);$$('dialog[open]').forEach(dialog=>dialog.close());
 if(['#community','#market'].includes(location.hash)){applyRoute();return}
 if(matchMedia('(prefers-reduced-motion: reduce)').matches){location.hash='community';return}
 if(gallery3D?.enter())return;
 $('#home').classList.add('is-leaving');enterTimer=setTimeout(()=>{location.hash='community'},220);
}
async function toggleFavorite(id){if(!requireMarketReady()||pendingFavorites.has(id))return;const restore=document.activeElement?.closest?.('[data-save]')?.dataset.save===id,next=!favorites.has(id);pendingFavorites.add(id);try{const result=await repository.setFavorite(id,next),piece=findPost(id);if(piece){if(isEngagementCount(result.favoriteCount))piece.favoriteCount=result.favoriteCount;else if(isEngagementCount(piece.favoriteCount))piece.favoriteCount=Math.max(0,piece.favoriteCount+Number(result.saved)-Number(!next))}result.saved?favorites.add(id):favorites.delete(id);render();if(restore){const target=$$('[data-save]').find(button=>button.dataset.save===id)||$('#market-title');target?.focus({preventScroll:true})}if($('#detail-dialog').open&&selectedId===id)updateDetailHeart();notify(result.saved?'saved_toast':'unsaved_toast')}catch(error){repositoryError(error)}finally{pendingFavorites.delete(id)}}

