function openDetail(id){if(!findPost(id))return;selectedId=id;renderDetail();if(!$('#detail-dialog').open)showDialog($('#detail-dialog'))}
async function deletePost(){const p=findPost(selectedId);if(!p?.mine||!requireMarketReady()||!confirm(t('delete_confirm')))return;const button=$('#delete-post');if(button?.disabled)return;if(button)button.disabled=true;try{await repository.deleteListing(p.id);posts=posts.filter(item=>item.id!==p.id);favorites.delete(p.id);$('#detail-dialog').close();render();notify('deleted_toast')}catch(error){repositoryError(error);if(button)button.disabled=false}}

function setError(key,field){activeError=key;$('#form-error').textContent=t(key);$('#form-error').hidden=false;if(field){const input=$('#'+field);const section=input.closest('details');if(section)section.open=true;input.setAttribute('aria-invalid','true');const descriptions=new Set((input.getAttribute('aria-describedby')||'').split(/\s+/).filter(Boolean));descriptions.add('form-error');input.setAttribute('aria-describedby',[...descriptions].join(' '));input.focus({preventScroll:true});input.scrollIntoView?.({block:'nearest'})}}
function clearError(){activeError=null;$('#form-error').hidden=true;$$('#sell-form [aria-invalid]').forEach(input=>{input.removeAttribute('aria-invalid');const descriptions=(input.getAttribute('aria-describedby')||'').split(/\s+/).filter(id=>id&&id!=='form-error');if(descriptions.length)input.setAttribute('aria-describedby',descriptions.join(' '));else input.removeAttribute('aria-describedby')})}
